import '../models/football_bingo.dart';

/// Two hundred authored daily career-grid layouts. Every grid is independently
/// authored (no axis-rotation padding) and every intersection is backed by a
/// verified real career record in football_bingo_careers.dart.
final footballBingoPuzzles = List<FootballBingoPuzzle>.generate(_blueprints.length, _puzzleForIndex, growable: false);

FootballBingoPuzzle _puzzleForIndex(int index) {
  final blueprint = _blueprints[index];
  return FootballBingoPuzzle(
    id: 'daily-career-v2-${(index + 1).toString().padLeft(3, '0')}',
    title: 'Career Grid ${(index + 1).toString().padLeft(3, '0')}',
    columns: blueprint.columns,
    rows: blueprint.rows,
    cells: [
      for (final entry in blueprint.players.entries)
        FootballBingoCell(
          id: '${index + 1}-${entry.key.replaceAll(':', '-')}',
          rowId: entry.key.split(':').first,
          columnId: entry.key.split(':').last,
          playerId: entry.value,
        ),
    ],
  );
}

class _Blueprint {
  const _Blueprint(this.rows, this.columns, this.players);
  final List<FootballBingoAxis> rows;
  final List<FootballBingoAxis> columns;
  final Map<String, String> players;
}

